def fitset(names):
    def model(p):
        w=p[0]; cols=[F[n] for n in names]+[np.cos(w*t),np.sin(w*t)]
        X=np.column_stack(cols)
        c,_,_,_=np.linalg.lstsq(X,dv_dt,rcond=None)
        return X@c-dv_dt
    best=None
    for w0 in [0.45,0.5,0.55]:
        r=least_squares(model,[w0])
        n=np.mean(r.fun**2)/np.var(dv_dt)
        if best is None or n<best[0]: best=(n,r.x)
    return best
